/* ============================================================================
 * GDOP base tokens — The source of truth for every color and design token.
 *
 *   • The docs Colors page parses this file and renders it (app/foundations/colors).
 *   • The shadcn registry item "base" ships this file as-is (registry.json → public/r/base.json).
 *   • The @theme block at the bottom is GENERATED from the declarations below
 *     (`npm run tokens:sync`). Edit tokens here; never edit the generated block.
 *
 * Authoring rules (the parser relies on them):
 *   1. Declarations live in `:root { }` (light) and `.dark { }` (overrides only).
 *   2. A comment line of the form  @group <kind> <id>: <description>  starts a group
 *      (see the groups below for examples).
 *      kinds: scale | semantic | tone | other.  scale/tone ids must match the token names:
 *      --<id>-<step> for scales, --tone-<id>-<role> for tones.
 *   3. One declaration per line. A short trailing comment becomes the token's description.
 *   4. Components use semantic + tone tokens. Scales are primitives.
 *
 * Install target: ~/app/base.css, then `@import "./base.css";` after `@import "tailwindcss";`.
 * ========================================================================== */

@custom-variant dark (&:is(.dark *));

:root {
  /* @group scale brand: Logo blue. #00549b is brand-700 (7.66:1 on white). */
  --brand-50: #f2f7fe;
  --brand-100: #e1eeff;
  --brand-200: #c2deff;
  --brand-300: #95c5fd;
  --brand-400: #6da5e5;
  --brand-500: #3e80c7;
  --brand-600: #2265a9;
  --brand-700: #00549b; /* logo blue */
  --brand-800: #043d72;
  --brand-900: #012a52;
  --brand-950: #001936;
}
